364→// ── CLI ───────────────────────────────────────────────────────────
365→if (import.meta.url === `file://${process.argv[1]}`) {
366→  const args = process.argv.slice(2);
367→  const flag = (n) => args.filter((a) => a.startsWith(`--${n}=`)).map((a) => a.slice(n.length + 3));
368→  const capturePaths = args.filter((a) => !a.startsWith("--"));
369→  if (capturePaths.length === 0) {
370→    console.error("usage: node collect-artifacts.mjs <capture.jsonl ...> [--task=f] [--diff=f] [--pre=path=file] [--json]");
371→    process.exit(2);
372→  }
373→
374→  const preChangeFiles = {};
375→  for (const spec of flag("pre")) {
376→    const at = spec.indexOf("=");
377→    if (at < 0) { console.error(`--pre expects <path>=<file>, got ${spec}`); process.exit(2); }
378→    preChangeFiles[spec.slice(0, at)] = readFileSync(spec.slice(at + 1), "utf8");
379→  }
380→
381→  const sessions = collectArtifacts({
382→    captureEvents: capturePaths.flatMap((p) => parseJsonl(readFileSync(p, "utf8"))),
383→    taskDescription: flag("task").map((p) => readFileSync(p, "utf8")).join("\n"),
384→    diff: flag("diff").map((p) => readFileSync(p, "utf8")).join("\n"),
385→    preChangeFiles,
386→    runId: flag("run-id")[0] || null,
387→    taskId: flag("task-id")[0] || null,
388→  });
389→
390→  const outPath = "evaluation/attribution/artifacts/run-artifacts.json";
391→  mkdirSync(dirname(outPath), { recursive: true });
392→  writeFileSync(outPath, JSON.stringify(sessions, null, 2), "utf8");
393→
394→  if (args.includes("--json")) console.log(JSON.stringify(sessions, null, 2));
395→  else console.log(renderArtifacts(sessions), `\nWritten to ${outPath}`);
396→}
