  const r = await probe("10.255.255.1", 9, { timeoutMs: 800 });
  assert.equal(r.ok, false);
  assert.ok(["timed out", "could not connect"].includes(r.why) || r.why.startsWith("error "), r.why);
  assert.ok(r.elapsed_ms < 5000);
